                        EmailAddresses = new List<string> { "karishma.saran@finddx.org", "lukschn@who.int", "saul.walker@cepi.net", "mandeep.dhaliwal@undp.org", "kasondem@who.int", "hinoue@worldbank.org", "s.birks@wellcome.org", "mranson@worldbank.org", "juribe@worldbank.org", "richard.hatchett@cepi.net", "niej@who.int", "farrarj@who.int", "kasolof@who.int", "peter.sands@theglobalfund.org", "masonc@who.int", "nazneen.damji@unwomen.org", "jorge.moreiradasilva@unops.org", "arai@ilo.org", "prasada@who.int", "nakarit@who.int", "dunetonp@unitaid.who.int", "kellyl@who.int", "dmarlow@gavi.org", "pendsera@who.int", "pfeifferm@who.int", "oaabdi@unicef.org", "mvledder@worldbank.org", "anguyen@gavi.org", "louisel@unops.org", "onabanjo@unfpa.org", "gomeze@unaids.org", "ja.rottingen@wellcome.org", "volks@who.int", "kohiri@gavi.org", "holloi@who.int", "hburris@gavi.org", "kasapie@who.int", "benjamin.syme@wfp.org", "brivalan@worldbank.org", "serhanfa@who.int", "hajjehr@who.int", "pendergasts@who.int", "brostroms@who.int", "francesca.colombo@oecd.org", "ursup@who.int", "tchaiban@unicef.org", "lonnquistf@who.int", "giancarlo.cirri@wfp.org", "jahrendts@gavi.org", "igor.oliynyk@theglobalfund.org", "perezcasasc@unitaid.who.int", "asmas@who.int", "jsi@cepi.net", "katie.kampf@theglobalfund.org", "freemanr@who.int", "zeck@unfpa.org", "kieran.daly@gatesfoundation.org", "chris.elias@gatesfoundation.org", "sergio.carmona@finddx.org", "aylwardb@who.int" },
