                new (
                    "00TQx0000073VjGMAU",
                    new UNOPSInteraction
                    {
                        Name = "Email: Danske fængselspladser i Kosovo",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-02-21").ToUniversalTime(),
                        Subject = "Email: Danske fængselspladser i Kosovo",
                        Description = "To: jengod@um.dk\nCC: naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Danske fængselspladser i Kosovo\nBody:\nHej Jens\nHåber alt er vel på Asiatisk Plads - eller hvor i verden du nu befinder dig. :-) \nJeg bemærkede i de danske medier, at Danmark nu har lejet 300 fængselspladser i Kosovo, og at eksisterende fængselspladser nu skal ombygges.  \nJeg er usikker på, om du er involveret i projektet - eller om du måske kan hjælpe mig med kontakt til de relevante i UM og JM? \nTanken herfra var blot, at det muligvis kunne være hensigtsmæssigt for jer at få et FN-agentur med stor erfaring i at bygge fængsler i hele verden efter de såkaldte Mandela-principper, til at stå for ombygningen af fængslet i Kosovo. Dermed sikrer I, at ombygningen sker på en måde, så der sikres ordentlige forhold for de indsatte. Vores evt. involvering i et sådant projekt kunne være enten blot teknisk rådgivning / udarbejde design til ansvar for hele ombygningen så der fx også sikres ordentlige arbejdsforhold under ombygningen.  \nHåber det kunne være af interesse for jer - og at du evt. kan hjælpe mig hen til rette kontor. \nUnder alle omstændigheder ville det være hyggeligt snart at mødes til en frokost eller kaffe! \nJeg ser frem til at høre fra dig. \nMvhAsbjørnAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx0000073VjGMAU",
                        EmailAddresses = new List<string> { "jengod@um.dk", "naimoh@unops.org" },
                        Status = (EntityStatus)1,
