                    new UNOPSInteraction
                    {
                        Name = "Email: Note Verbale from UNOPS to The Ministry of Foreign Affairs of Finland",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-02-27").ToUniversalTime(),
                        Subject = "Email: Note Verbale from UNOPS to The Ministry of Foreign Affairs of Finland",
                        Description = "To: Hanna.Rantala@gov.fi\nCC: satu.lassila@formin.fi; Andrea.Tanzi-Albi@gov.fi; nielsg@unops.org; victoriac@unops.org; naimoh@unops.org; emiliep@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Note Verbale from UNOPS to The Ministry of Foreign Affairs of Finland\nBody:\nDear Hanna, \nFollowing up on our previous constructive conversations, please find attached to this email for your kind attention: A Note Verbale from The Office in the Republic of Finland of the United Nations Office for Project Services (UNOPS) to the Ministry for Foreign Affairs of the Republic of Finland in which we kindly ask for your assistance in reinstating an ID card and a temporary residence permit for Ms. Nan Li - a UNOPS employee within UNOPS’ Global Portfolios Office portfolio, which includes the UN Global Pulse program based in Helsinki. An application form from Ms. Nan Li. A copy of Ms. Nan Li's passport. A photo of Ms. Nan Li. The package is also being sent to you physically from our Helsinki based office. \nThank you very much for your kind attention and your always helpful cooperation. \nAs always, please do not hesitate to reach out for any inquiries. \nKind regards,Asbjørn\n\nAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000007J5jSMAS",
                        EmailAddresses = new List<string> { "satu.lassila@formin.fi", "nielsg@unops.org", "emiliep@unops.org", "naimoh@unops.org", "andrea.tanzi-albi@gov.fi", "hanna.rantala@gov.fi", "victoriac@unops.org" },
