                ),
                new (
                    "00TQx000007Se6YMAS",
                    new UNOPSInteraction
                    {
                        Name = "Email: Letter for Ambassador Andrii Yanevskyi",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-03-01").ToUniversalTime(),
                        Subject = "Email: Letter for Ambassador Andrii Yanevskyi",
                        Description = "To: anton.rybak@mfa.gov.ua\nCC: sarahdg@unops.org; waingchita@unops.org; naimoh@unops.org; timl@unops.org; emiliep@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Letter for Ambassador Andrii Yanevskyi\nBody:\nDear Anton, \nI hope this email finds you well. \nPlease find attached a letter from UN Under-Secretary-General, Mr. Jorge Moreira da Silva for ambassador Andrii Yanevskyi in which he is kindly invited for a meeting to get introduced and to discuss our ongoing collaboration. \nI look forward to hearing from you and to finding a time slot convenient for the ambassador to meet with the UN Under-Secretary-General. \nWishing you a nice weekend once you get there. \nBest regards,AsbjørnAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000007Se6YMAS",
                        EmailAddresses = new List<string> { "waingchita@unops.org", "anton.rybak@mfa.gov.ua", "emiliep@unops.org", "naimoh@unops.org", "sarahdg@unops.org", "timl@unops.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
                        CreatedDate = new DateTime(2024, 3, 1, 10, 3, 15, DateTimeKind.Utc),
                        LastModifiedBy = 0,
                        LastModifiedDate = DateTime.UtcNow,
                        IsDeleted = false,
                        DeletedBy = 0
                    },
                    new List<string> {  },
                    new List<int> { 1123 },
                    new List<string> { "asbjornb@unops.org" },
                    new List<string> { "B0047" }
                ),
                new (
                    "00TQx000007ZCC8MAO",
                    new UNOPSInteraction
                    {
                        Name = "Email: Re: Embassy of Sweden in Denmark - UNOPS",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-03-04").ToUniversalTime(),
                        Subject = "Email: Re: Embassy of Sweden in Denmark - UNOPS",
                        Description = "To: adrian.garpvall@gov.se\nCC: anders.carlsson@gov.se; naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Re: Embassy of Sweden in Denmark - UNOPS\nBody:\nHi Adrian, \nThank you for your email and a pleasant introduction meeting. \nI would be very happy to engage with you and your colleagues in Stockholm to promote a UN career for Swedish nationals. \nPlease do not hesitate to reach out to us once you are further in the process and would like to engage in a dialogue on how together we can work on this. \nWe remain as always at your disposal. \nBest regards, Asbjørn\n\nOn Fri, 1 Mar 2024 at 15:49, Adrian Garpvall <adrian.garpvall@gov.se> wrote:\n\n\n\n\n\n\n\n\nDear Asbjørn,\n \nWe would like to thank you and Naimo for our latest meeting and the invitation to the UN City.\n \nWith reference to our discussion on Swedish nationals in the UN system, Stockholm has informed us that there are a number of initiatives in the pipeline. Among other things, a database will be created at the ministry\n of Swedish civil servants that have expressed an interest in UN-work, which will be used to encourage suitable applicants to apply to specific job openings. This will be coupled by more direct assistance in the application process. The database will be launched\n later on in the Spring.\n \nWe would therefore very much like to maintain contact with you and your department regarding job openings within UNOPS, but also to continue the discussions regarding ways of growing the Swedish representation.\n \nI wish you a great weekend.\n \nBest regards, \nAdrian\n \nAdrian Garpvall\nSveriges Ambassad\nAmaliegade 5A, 1256 Köpenhamn K\nMobil +45 27 14 82 67\n\nadrian.garpvall@gov.se\n\nwww.regeringen.se\nwww.swedenabroad.com/kopenhamn\n\n\n\n \n \n\n\n\nAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000007ZCC8MAO",
                        EmailAddresses = new List<string> { "naimoh@unops.org", "anders.carlsson@gov.se", "adrian.garpvall@gov.se" },
                        Status = (EntityStatus)1,
