                new (
                    "00TQx000007uPfoMAE",
                    new UNOPSInteraction
                    {
                        Name = "Email: Launch of a new, reinforced Danish engagement in Africa: Call for dialogue with Danish embassies",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-03-12").ToUniversalTime(),
                        Subject = "Email: Launch of a new, reinforced Danish engagement in Africa: Call for dialogue with Danish embassies",
                        Description = "To: dalilag@unops.org\nCC: hawas@unops.org; leonardinaR@unops.org; amyn@unops.org; jakobt@unops.org; IfeomaCM@unops.org; TatianaW@unops.org; rainerf@unops.org; WorkneshG@unops.org; emiliep@unops.org; naimoh@unops.org; djenebas@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Launch of a new, reinforced Danish engagement in Africa: Call for dialogue with Danish embassies\nBody:\nDear Dalila and colleagues, \nYesterday I attended an event that launched the drafting of a new reinforced Danish approach to engagements in Africa - spearheaded by the Danish Prime Minister (Mette Frederiksen), the Minister for Foreign Affairs (Lars Løkke Rasmussen) and the Minister for Development Cooperation and Global Climate (Dan Jørgensen). The kick-off event also featured Kenya's Minister for Foreign Affairs (Dr. Musalia Mudavadi) as well as Sierra Leone's Chief Minister (David Sengeh). \nThe event marked the initiation of a dialogue with partners that will lead to a new Africa plan for the Danish government - to be finalised by August, 2024. The Danish government has encouraged stakeholders to engage and to inform them about what this new strategy should contain. \nNow is therefore an excellent opportunity to engage in conversations with our local colleagues at the Danish embassies throughout Africa on how UNOPS' capacities can underpin the strengthened Danish engagement. \nAt the kick-off event the Prime Minister emphasised that the new Africa strategy must be based on an equal and respectful partnership that took into consideration that Africa consists of 54 individual countries.\nThe Prime Minister also underlined her own personal engagement with Africa, being one of the only western prime ministers with a master in Africa studies.  \nSome of the key topics for the new Africa strategy would likely be: EducationGreen transition Sustainable energyPublic-Private PartnershipsFighting poverty and hungerCreating jobs and growthAs this event marked the launch of the dialogue, I hope that colleagues would use this as an opportunity to approach local Danish embassies and engage in conversations on which areas UNOPS can support. \n\nMy colleague @Naimo HASSAN HIRSI and I remain at your disposal for any further intel on Danish development aid, contact points, tips & tricks, etc. when engaging with the Danes.  \nBest regards,AsbjørnAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000007uPfoMAE",
                        EmailAddresses = new List<string> { "djenebas@unops.org", "tatianaw@unops.org", "dalilag@unops.org", "leonardinar@unops.org", "jakobt@unops.org", "emiliep@unops.org", "amyn@unops.org", "naimoh@unops.org", "workneshg@unops.org", "hawas@unops.org", "rainerf@unops.org", "ifeomacm@unops.org" },
