                new (
                    "00TQx000007xTjWMAU",
                    new UNOPSInteraction
                    {
                        Name = "Email: Muligt projekt i Moldova: Håndtering af ukrainske flygtninge",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-03-13").ToUniversalTime(),
                        Subject = "Email: Muligt projekt i Moldova: Håndtering af ukrainske flygtninge",
                        Description = "To: jassor@um.dk; mrasmu@um.dk; annkah@um.dk\nCC: jengod@um.dk; naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Muligt projekt i Moldova: Håndtering af ukrainske flygtninge\nBody:\nKære Anne, Marianne og Jasmin, \nJeg rækker ud til jer for at flage et mindre projekt i Moldova, som muligvis kunne være i dansk interesse. \nProjektet handler om at hjælpe Moldova med håndteringen af de op mod 1 million flygtninge, som er flygtet fra Ukraine til Moldova siden december 2023. En meget stor andel af de ukrainske flygtninge er udsatte personer, som kræver særlig hjælp. \nMyndighederne i Moldova har meget vanskeligt ved at håndtere situationen, som de ikke har administrativ kapacitet til - endsige den fysiske infrastruktur. Den centrale myndighed udgøres af Generaldirektoratet for Migration (\"Inspectorate General for Migration\" - GIM) som står for håndteringen af flygtningenes sikkerhed, ansøgningsprocessen osv. \nGeneraldirektoratet for Migration har pt. en meget gammel og faldefærdig bygning i Chisinau (se billede øverst i vedlagte), som ikke kan håndtere det voldsomme flygtningepres. Myndighederne i Moldova har derfor bedt om hjælp til at opgradere bygningen for at kunne håndtere flygtningene og sørge for ordentlige faciliteter for dem. \nI samarbejde med Moldovas indenrigsministerium har vi udarbejdet vedlagte konceptnote, som angiver en første fase i et projekt som senere kan udvides til en egentlig opgradering af bygningen. I denne første fase klarlægges de konkrete behov, der udarbejdes optioner for et evt. efterfølgende opgraderingarbejde og der udarbejdes budgetestimater for det efterfølgende genopbygningsarbejde. Altså forarbejdet til en egentlig reparation / udvidelse af Generaldirektoratet for Migration. \nProjektet estimeres til omkring 1-1,2 mio. kr. og kan udføres på ca. 3 måneder, hvorefter der vil forelægge en plan for det efterfølgende konstruktionsarbejde, budget herfor, optioner mv. Men nærværende projekt forpligtiger man sig således ikke til mere end ovenstående - hvorefter en evt. anden (eller flere) donorer vil kunne gennemføre selve konstruktionsarbejdet. \nJeg håber at projektet muligvis har vakt jeres interesse. Jeg forstår at der er en stor prioritet for regeringen i Moldova. \nBåde jeg og vores kolleger i Ukraine og Moldova står naturligvis til jeres rådighed for en evt. opfølgende dialog - såfremt dette kunne have jeres interesse. \nPå forhånd mange tak. \nMvhAsbjørnAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000007xTjWMAU",
