                new (
                    "00TQx000008m1dCMAQ",
                    new UNOPSInteraction
                    {
                        Name = "Email: Opdateret konceptnote vedr. fase 1 modernisering af migrationsbygning i Moldova",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-04-02").ToUniversalTime(),
                        Subject = "Email: Opdateret konceptnote vedr. fase 1 modernisering af migrationsbygning i Moldova",
                        Description = "To: annkah@um.dk; mrasmu@um.dk\nCC: naimoh@unops.org; jassor@um.dk\nBCC: \nAttachment: --none--\n\nSubject: Opdateret konceptnote vedr. fase 1 modernisering af migrationsbygning i Moldova\nBody:\nKære Anne, Marianne og Jasmin,\nHåber I har nydt en velfortjent påskeferie - og at i hvert fald Jasmin muligvis stadig holder lidt ferie. :-) \nEfter dialog med Moldovas migrationsmyndigheder har vi opdateret den tidligere fremsendte konceptnote vedr. en fase 1 i moderniseringen af immigrationsbygningen i Chișinău, jf. vedlagte. \nI den opdaterede konceptnote har vi indarbejdet baggrundsfakta vedr. antallet af flygtninge fra Ukraine i Moldova med henblik på at anskueliggøre problemstillingen med kapacitet til at håndtere flygtningene. \nLad mig endelig vide om det kunne have jeres interesse at indgå evt. samarbejde herom. \nMvhAsbjørn\nAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000008m1dCMAQ",
                        EmailAddresses = new List<string> { "mrasmu@um.dk", "jassor@um.dk", "naimoh@unops.org", "annkah@um.dk" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
