                ),
                new (
                    "00TQx000009BiDSMA0",
                    new UNOPSInteraction
                    {
                        Name = "Email: Project proposal for the complete restoration of Arkas Gymnasium in Mykolaiv",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-04-11").ToUniversalTime(),
                        Subject = "Email: Project proposal for the complete restoration of Arkas Gymnasium in Mykolaiv",
                        Description = "To: mrasmu@um.dk; annkah@um.dk\nCC: timl@unops.org; eleneag@unops.org; arunn@unops.org; teresam@unops.org; janphilipk@unops.org; svitlanas@unops.org; svitlanaz@unops.org; naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Project proposal for the complete restoration of Arkas Gymnasium in Mykolaiv\nBody:\nDear Anne and Marianne, \n\nFollowing up on our latest conversation, please find attached for your consideration a proposal for a restoration of the Arkas Gymnasium in Mykolaiv. \nThe proposal contains two options with an additional option of furnishing the school with IT equipment, sports items, furniture etc.  Restoration of the damaged parts of the building as well as completion of the sheltersBudget: 3.7 million USDTimeframe: 18 months\n\nComplete restoration of the building allowing for the physical return of the students Budget: 6.4 million USDTimeframe: 25 months\n\nFurnishing of IT, sports and furniture: Budget: 0.6 (additional) \nWe look very much forward to hearing back from you and remain at your disposal for a follow up conversation on the proposal attached. \nBest regards,Asbjørn Asbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000009BiDSMA0",
                        EmailAddresses = new List<string> { "svitlanas@unops.org", "arunn@unops.org", "mrasmu@um.dk", "janphilipk@unops.org", "naimoh@unops.org", "svitlanaz@unops.org", "eleneag@unops.org", "annkah@um.dk", "timl@unops.org", "teresam@unops.org" },
