                    "00TQx000009yytrMAA",
                    new UNOPSInteraction
                    {
                        Name = "Email: Sixth Humanitarian Senior Officials Meeting on Yemen – invitation and agenda",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-04-29").ToUniversalTime(),
                        Subject = "Email: Sixth Humanitarian Senior Officials Meeting on Yemen – invitation and agenda",
                        Description = "To: ECHO-C3@ec.europa.eu\nCC: Ramon.VAN-BARNEVELD@ec.europa.eu; Patrice.LENORMAND@ec.europa.eu; Valentina.DE-BERNARDI@ec.europa.eu; Martina.GHELARDUCCI@ec.europa.eu; Anne.DECAILLET@ec.europa.eu; Ani.NEDKOVA@ec.europa.eu; Elena.DIKOMITIS@ec.europa.eu; Judith.BLANCO-GUILLEN@ec.europa.eu; Heather.Blackwell@echofield.eu; Muriel.Cornelis@echofield.eu; Felix.Leger@echofield.eu; Francesco.Rigamonti@echofield.eu; Sania.Al-Aswadi@echofield.eu; sofia.h.karlsson@gov.se; adel.elsayed.sparr@gov.se; Andreas.PAPACONSTANTINOU@ec.europa.eu; Eirini.DIGKA@ec.europa.eu\nBCC: \nAttachment: --none--\n\nSubject: Sixth Humanitarian Senior Officials Meeting on Yemen – invitation and agenda\nBody:\nDear Madam, Dear Sir, \n \nWe have the pleasure to invite you, on behalf of Mr. Andreas Papaconstantinou, Director Neighbourhood, Middle East, South-West and Central Asia of DG ECHO, European Commission and of Mr Carl Hartzell, Deputy\n Director General and Head of the Department for Multilateral Governance and Humanitarian Policy, Ministry for Foreign Affairs of Sweden, to the\nsixth Humanitarian Senior Officials Meeting on Yemen,\nthat we are co-organising on the\n7th of May 2024.\n\n \nYou will find attached to this mail a formal invitation and the provisional agenda of the meeting.\n \nParticipating countries and organisations are encouraged to communicate the name of in person participating representatives (maximum of 2 delegates) to our Coordination Team:\n  ECHO-C3@ec.europa.eu  (if not yet done)\nby Friday 3 May c.o.b , \n \nLooking forward to a fruitful discussion.\n \nSofia H. Karlsson and Patrice Lenormand\n \nECHO C3 SECRETARIAT\n\n \n \n\n\nEuropean Commission\nDirectorate-General for European Civil Protection and Humanitarian Aid Operations\nECHO. C –\nNeighbourhood, Middle East, South-West and Central Asia\n\nUnit C.3 – South-West Asia and Arabian Peninsula \nL-86 02/23\n\nB-1049 Brussels/Belgium\n\n+32 2 295 34 88",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx000009yytrMAA",
                        EmailAddresses = new List<string> { "felix.leger@echofield.eu", "martina.ghelarducci@ec.europa.eu", "judith.blanco-guillen@ec.europa.eu", "heather.blackwell@echofield.eu", "muriel.cornelis@echofield.eu", "sofia.h.karlsson@gov.se", "patrice.lenormand@ec.europa.eu", "adel.elsayed.sparr@gov.se", "andreas.papaconstantinou@ec.europa.eu", "sania.al-aswadi@echofield.eu", "ramon.van-barneveld@ec.europa.eu", "eirini.digka@ec.europa.eu", "ani.nedkova@ec.europa.eu", "francesco.rigamonti@echofield.eu", "elena.dikomitis@ec.europa.eu", "anne.decaillet@ec.europa.eu", "echo-c3@ec.europa.eu", "valentina.de-bernardi@ec.europa.eu" },
