                new (
                    "00TQx00000A2J2QMAV",
                    new UNOPSInteraction
                    {
                        Name = "Email: Re: Ansøgningen - A. P. Møller Fonden",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-05-01").ToUniversalTime(),
                        Subject = "Email: Re: Ansøgningen - A. P. Møller Fonden",
                        Description = "To: mett@eifo.dk\nCC: msec@eifo.dk\nBCC: \nAttachment: --none--\n\nSubject: Re: Ansøgningen - A. P. Møller Fonden\nBody:\nKære Mette\nMange tak for fint udkast til ansøgningen. \nJeg har indsat et par mindre forslag med TC i vedlagte. Dette særligt mhp. at gøre det klart, at der vil skulle udarbejdes en mere detaljeret projektbeskrivelse, som også er valideret af vores folk samt en kontrakt mellem AP Møller Fonden, Olena Zelenska Foundation og UNOPS som bl.a. tydeliggør fordelingen af ansvar for de forskellige elementer i implementeringen. Det er klart, at den proces kan føre til justeringer af den beskrivelse vi her lægger op til i ansøgningen. \nJeg vil nu samle relevante folk her i UNOPS mhp. at få deres umiddelbare vurdering af, hvordan et konkret setup, ansvarsfordeling og aftaletekst kunne se ud. Derefter vil jeg foreslå at vi tager et møde med Mathias og du, mhp. at forsøge at afklare deres spørgsmål og teste deres ideer til et setup af på jer - inden vi rækker ud til AP Møller Fonden og Olena Zelenska Foundation. \nMvhAsbjørn\n\nOn Wed, 1 May 2024 at 08:53, Mette Thybo <mett@eifo.dk> wrote:\n\n\n\n\n\n\n\n\nHej Asbjørn\n\n\n\nHermed udkast til ansøgningen til A. P. Møller Fonden. Som nævnt skal jeg sende den i dag til dem.\n\n\n\n\nRing endelig, hvis der er noget vi skal vende. \n\n\n\nMvh\nMette\n \n\n\n\n\n\n\nVenlig hilsen\nMette Thybo\nChefkonsulent / Principal Consultant\n\n\n\n\n\nM:\nT:\n\n\n+45 24 90 22 38 | E: mett@eifo.dk\n+45 70 60 49 60 | www.eifo.dk",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000A2J2QMAV",
                        EmailAddresses = new List<string> { "msec@eifo.dk", "mett@eifo.dk" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
