                new (
                    "00TQx00000A2gdPMAR",
                    new UNOPSInteraction
                    {
                        Name = "Email: UNOPS WHO PAHO",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-05-01").ToUniversalTime(),
                        Subject = "Email: UNOPS WHO PAHO",
                        Description = "To: director@paho.org\nCC: \nBCC: \nAttachment: --none--\n\nSubject: UNOPS WHO PAHO\nBody:\nDear Jarbas\n\nFurther to our chat on Linked In, I am sorry to miss you in DC next week and wish you a good mission in Jamaica!\nMy colleague Christine Bowers from our Washington Liaison office has reached out to Luis Jiminez to help connect us to colleagues in health systems, procurement and emergencies (Ciro is my old colleague from WHE!).\nPerhaps we can try again to meet in Geneva during the World Health Assembly?\n\nBest wishes and safe travels!\nLouise\nLouise Leech, MPH  | Head of Geneva Liaison Office | Partnerships and Liaison Group | Mobile: +41 79 343 1614  UNOPS / Office des Nations Unies pour les Services Unité de Gestion du Projet\nGlobal project overview here  |  Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000A2gdPMAR",
