                ),
                new (
                    "00TQx00000ArsfuMAB",
                    new UNOPSInteraction
                    {
                        Name = "Email: Fwd: FW: Visit of the Swedish Committee on Foreign Affairs",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-05-22").ToUniversalTime(),
                        Subject = "Email: Fwd: FW: Visit of the Swedish Committee on Foreign Affairs",
                        Description = "To: sarahdg@unops.org; alexandram@unops.org\nCC: emiliep@unops.org; naimoh@unops.org; annag@unops.org; hilaryb@unops.org; jorge.moreiradasilva@unops.org; sonjalk@unops.org; waingchita@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Fwd: FW: Visit of the Swedish Committee on Foreign Affairs\nBody:\nDear Sarah and Alexandra, \nWould Jorge - or alternatively Sonja - be available to meet the Swedish Parliament's Foreign Affairs Committee on Tuesday, May 28 at some point before lunch here at the UN City, cf. below? \nThe Foreign Affairs Committee consists of 12 fairly high ranking Swedish parliamentarians from The Sweden Democrats, The Social Democratic Party, The Moderate Party, The Liberal Party, The Left Party, The Christian Democrats, The Center Party and The Green Party.\nThank you in advance for your attention given the short timeframe. \nBest,Asbjørn\n\n---------- Forwarded message ---------\nFrom: Glenn Slaikjaer <glenn.slaikjaer@gov.se>\nDate: Wed, 22 May 2024 at 14:14\nSubject: FW: Visit of the Swedish Committee on Foreign Affairs\nTo: Asbjorn BRINK <asbjornb@unops.org>\n\n\n\n\n\n\n\n\n\nKære Asbjørn\n \nHer har du mailen – og som jeg nævnte, så er vi ikke så kræsne i forhold til, hvem som evt. kan tage i mod fra jer.\n \nTusinde tak for hjælpen.\n \n \n\nMed venlig hilsen\n \nGlenn\n\n \n\n\nFrom: Glenn Slaikjaer\n\n\nSent: den 15 maj 2024 11:57\n\nTo: 'executive.office@unops.org' <executive.office@unops.org>\n\nSubject: Visit of the Swedish Committee on Foreign Affairs\n\n\n \nDear Sir/Madam,\n \nWe have the Swedish Committee on Foreign Affairs from our Parliament on a visit to Copenhagen on 28 May.\n \nThey would very much like to visit the Un City and meet with your Executive Director.\n \nWould you be able to host the group of MPs for a meeting before lunch?\n \n \nBest regards,\n \nGlenn\n \nGlenn Vestergaard Slaikjär\nSocial Secretary and Consular Officer\nEmbassy of Sweden\nAmaliegade 5A, 1256 Copenhagen K, Denmark\nTel: +45 33 36 03 90\nCell : +45 26 73 60 36\nglenn.slaikjaer@gov.se",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000ArsfuMAB",
                        EmailAddresses = new List<string> { "waingchita@unops.org", "jorge.moreiradasilva@unops.org", "emiliep@unops.org", "sonjalk@unops.org", "alexandram@unops.org", "naimoh@unops.org", "hilaryb@unops.org", "sarahdg@unops.org", "asbjornb@unops.org", "annag@unops.org", "executive.office@unops.org", "glenn.slaikjaer@gov.se" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
