                ),
                new (
                    "00TQx00000ArwQ1MAJ",
                    new UNOPSInteraction
                    {
                        Name = "Email: Re: Muligt projekt i Moldova vedr. håndtering af ukrainske flygtninge",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-05-22").ToUniversalTime(),
                        Subject = "Email: Re: Muligt projekt i Moldova vedr. håndtering af ukrainske flygtninge",
                        Description = "To: Tale.Kvalvaag@norad.no\nCC: naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Re: Muligt projekt i Moldova vedr. håndtering af ukrainske flygtninge\nBody:\nKære Tale\nDet er fint - mange tak! \nJeg tænker at det kunne være et udmærket, mindre projekt, hvor NORAD kunne se hvad UNOPS kan levere af konkrete projekter på jorden. \nJeg ser meget frem til at høre fra jer. \nMvhAsbjørn\nOn Wed, 22 May 2024 at 13:36, Kvalvaag, Tale <Tale.Kvalvaag@norad.no> wrote:\n\n\n\n\n\n\n\n\nKjære Asbjørn,\n \nTakk for e-posten nedenfor! Håper alt står bra til med deg også!\n \nJeg har delt prosjektforslaget med noen kolleger og vi vil komme tilbake til deg.\n \nVennlig hilsen\n\nTale\n \n\nFrom: Asbjorn BRINK <asbjornb@unops.org>\n\n\nSent: Tuesday, May 14, 2024 3:25 PM\n\nTo: Kvalvaag, Tale <Tale.Kvalvaag@norad.no>\n\nCc: Naimo HASSAN HIRSI <naimoh@unops.org>\n\nSubject: Muligt projekt i Moldova vedr. håndtering af ukrainske flygtninge\n\n \n\nKære Tale, \n\n \n\n\nJeg håber alt er godt i Oslo - og at sommeren også langsomt er ved at komme til jer med varmere vejr og sol. \n\n\n \n\n\nJeg rækker ud til dig mhp. at drøfte et projekt som muligvis kunne være i norsk interesse i Moldova. Jeg vedlægger en kort konceptnote om projektet, som handler om migrationsbygningen i Chișinău, som er i meget dårlig stand. Bygningen er\n modtagecenter for de over 115.000 ukrainske flygtninge som indtil videre er flygtet til Moldova, hvoraf langt de fleste er udsatte borgere. \n\n\n \n\n\nMyndighederne i Moldova har meget vanskeligt ved at håndtere den store strøm af flygtninge og har ad flere omgange anmodet om hjælp til genopbygning af infrastruktur til håndteringen. Det vedlagte projekt er en særlig stor prioritet fra\n Moldova, som omhandler en første fase som vil skulle kortlægge behovene og udarbejde et konkret forslag til udbygningen af faciliteterne. \n\n\n \n\n\nKonkret er der tale om en mindre projekt til omkring 150.000-175.000 USD, som vil finansiere forberedelsen af en egentlig udbygning af migrationsmyndigheden (som evt. kan finansieres af andre eller flere donorer). Dvs. en analyse af hob,\n et concept design, en projekt plan samt budgetestimater for en fuld genopbygning. \n\n\n \n\n\nJeg håber at I finder projektet interessant, der som bekendt er meget efterspurgt i Moldova til håndtering af de mange ukrainske flygtninge. \n\n\n \n\n\nHvis I har interesse for projektet, vil vi naturligvis meget gerne mødes med henblik på at drøfte nærmere om videre vej frem. \n\n\n \n\n\nMvh\n\n\nAsbjørn \n\n\n \n\n\n\n\n\n\n\nAsbjørn Brink | Head\n of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS\n HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org\n\n \n\nKeep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube \n\nSubscribe to our external newsletter in\nEnglish,\nFrench\n or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000ArwQ1MAJ",
                        EmailAddresses = new List<string> { "asbjornb@unops.org", "tale.kvalvaag@norad.no", "naimoh@unops.org" },
                        Status = (EntityStatus)1,
