                        GmailMessageId = "00TQx00000B3IQYMA3",
                        EmailAddresses = new List<string> { "laetitiak@unops.org", "usmana@unops.org", "sofia.h.karlsson@gov.se", "martina.ghelarducci@ec.europa.eu", "judith.blanco-guillen@ec.europa.eu", "patrice.lenormand@ec.europa.eu", "adel.elsayed.sparr@gov.se", "ani.nedkova@ec.europa.eu", "jeromedt@unops.org", "elena.dikomitis@ec.europa.eu", "anne.decaillet@ec.europa.eu", "echo-c3@ec.europa.eu" },
