                        EmailAddresses = new List<string> { "entelas@unops.org", "zeinabth@unops.org", "tatianaw@unops.org", "boite@un.org", "galinierp@un.org", "tresorsafari1@gmail.com", "emiliep@unops.org", "ulbrich@un.org", "duwana@un.org", "herrmann1@un.org", "haynes2@un.org", "victoriac@unops.org", "icscommittee0@gmail.com", "ocholla@un.org", "lorrainea@unops.org", "raady@unops.org", "dalilag@unops.org", "davidc@unops.org", "ramouh@unops.org", "valeriek@unops.org", "amelia.hannaford@un.org", "ceesaye@un.org", "tjitske.dejong@un.org", "rizkallahe@un.org", "gssc.ica.unops.admin@unops.org", "jessica.davila-ardittis@un.org", "dove@un.org", "jeannes@unops.org", "jeanne.diokhpsadio@un.org", "vahard@un.org", "girukwayo@un.org", "kisemboserge1984@gmail.com", "monusco-legal@un.org", "fredericfr@unops.org", "unoms@un.org", "kannehb@un.org", "rocheteau@un.org", "arnauds@unops.org", "laurentium@unops.org", "nadians@unops.org", "keita31@un.org", "alejoe@unops.org", "saraho@unops.org", "zervos@un.org", "amadut@un.org" },
