                new (
                    "00TQx00000BAdONMA1",
                    new UNOPSInteraction
                    {
                        Name = "Email: UNHCR introduction of Health Insurance",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-05-29").ToUniversalTime(),
                        Subject = "Email: UNHCR introduction of Health Insurance",
                        Description = "To: victoriac@unops.org; alejoe@unops.org; annelisev@unops.org; michaelap@unops.org\nCC: arnauds@unops.org; laurentium@unops.org\nBCC: \nAttachment: --none--\n\nSubject: UNHCR introduction of Health Insurance\nBody:\nDear colleagues,\nI hope this email finds you well.\nI am writing to inform you that you will be receiving an email from our partner, UNHCR, regarding a significant initiative they are undertaking. They will be reaching out to you as a valued partner to inform you of their exciting news. No action is required on your part. \nThe email from UNHCR will provide a briefing about the introduction of a comprehensive health insurance coverage through Cigna for the International ICAs (effective 01 Sep 2024). This initiative is the result of a thorough risk analysis and a commitment to creating equality and ensuring the well-being of all employees. More details will follow.\n\nBest regards,Lorraine-- \nLorraine Anabtawi | HR Partnerships Specialist | Partnerships and Liaison Group |\nUNOPS | Tel: 972548174189 | Skype:\nlorraine.anabtawi | www.unops.org | Supplying value, delivering results,\nchanging lives\n\n \n\nKeep up-to-date\nwith UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to\nour external newsletter in English, French or Spanish",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000BAdONMA1",
                        EmailAddresses = new List<string> { "arnauds@unops.org", "laurentium@unops.org", "alejoe@unops.org", "michaelap@unops.org", "annelisev@unops.org", "victoriac@unops.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("lorrainea@unops.org".ToLower()) ? paoUserEmailMapping["lorrainea@unops.org".ToLower()] : 0,
                        CreatedDate = new DateTime(2024, 5, 29, 17, 9, 17, DateTimeKind.Utc),
