                        EmailAddresses = new List<string> { "maria.de.la.luna@unwomen.org", "arnauds@unops.org", "michaelri@unops.org", "daniele@unops.org", "emiliep@unops.org", "akhtar.zazai@unwomen.org", "anton.kukoba@unwomen.org", "laetitia.mpofu@unwomen.org", "hodan.addou@unwomen.org", "adam.simpson@unwomen.org", "artan.aliko@unwomen.org", "alicia.ziffer@unwomen.org", "irena.sabados@unwomen.org", "natascha.paddison@unwomen.org", "daniel.seymour@unwomen.org", "mikaelag@unops.org", "jacqueline.gordillo@unwomen.org" },
