                new (
                    "00TQx00000C2Z2vMAF",
                    new UNOPSInteraction
                    {
                        Name = "Email: UNOPS hedging",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-06-19").ToUniversalTime(),
                        Subject = "Email: UNOPS hedging",
                        Description = "To: iraklij@unops.org; Miguel.HOYAS-GARCIA@ec.europa.eu; Paolo.SERGIO@ec.europa.eu\nCC: laetitiak@unops.org; mariacarmenco@unops.org; Marion.REFFAY@ec.europa.eu; svene@unops.org\nBCC: \nAttachment: --none--\n\nSubject: UNOPS hedging\nBody:\nDear colleagues,\n \nAs agreed, please find below the connection details for our meeting.\n\n\nBest,\n \nMiguel\n \n\n\n________________________________________________________________________________\n\n\nMicrosoft Teams\nNeed help?\n\n\n\nJoin\n the meeting now \n\n\nMeeting ID:\n352 462 915 786\n\n\n\nPasscode:\nFFkpGR\n\n\n\n\n\n\n\n\nJoin on a video conferencing device\n\n\n\nTenant key:\nteams@vteams.tech.ec.europa.eu\n\n\n\nVideo ID:\n122 326 536 0\n\n\n\nMore\n info \n\n\nFor organizers:\nMeeting\n options \n\n\n\nJoining is available only from a Commission videoconferencing system. If E2EE option is enabled, for SNC purposes, please join from the Teams desktop\n or mobile app.\n\n\n\nOrg help\n\n\n\n________________________________________________________________________________",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000C2Z2vMAF",
                        EmailAddresses = new List<string> { "marion.reffay@ec.europa.eu", "laetitiak@unops.org", "teams@vteams.tech.ec.europa.eu", "miguel.hoyas-garcia@ec.europa.eu", "paolo.sergio@ec.europa.eu", "mariacarmenco@unops.org", "svene@unops.org", "iraklij@unops.org" },
