                new (
                    "00TQx00000C2dwDMAR",
                    new UNOPSInteraction
                    {
                        Name = "Email: RE: EU Statement @UNOPS EB",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-06-17").ToUniversalTime(),
                        Subject = "Email: RE: EU Statement @UNOPS EB",
                        Description = "To: mariacarmenco@unops.org\nCC: \nBCC: \nAttachment: --none--\n\nSubject: RE: EU Statement @UNOPS EB\nBody:\nMerci Carmen.\nJe n’étais pas impliqué.\n\nLes Collègues de la D2 ont dû être consultés.\n\nUNOPS jouit d’une bonne réputation.\n\nÀ bientôt,\nLuc\n \n\nFrom: Mariacarmen COLITTI <mariacarmenco@unops.org>\n\n\nSent: Monday, June 17, 2024 4:15 PM\n\nTo: BAGUR Luc (INTPA) <Luc.Bagur@ec.europa.eu>\n\nSubject: EU Statement @UNOPS EB\n\n \n\n\nCher Luc,\n\n\n \n\n\nComme discuté lors de notre conversation au FAFA WG, voici le discours de l’UE a notre Board.\n\n\n \n\n\nhttps://www.eeas.europa.eu/delegations/un-new-york/eu-statement-–-joint-executive-boards-undp-unfpa-and-unops-dialogue-unops-executive-director_en?s=63\n\n\n \n\nÀ bientôt\n\n\nCarmen\n\n\n\n\n\nMariacarmen Colitti | Head of Office and Representative | Partnerships and Liaison Group | Brussels Liaison Office | Brussels, Belgium | Tel: + 32 2 7881840|\n\nwww.unops.org \n\n\n\nKeep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube.\n\n\nSubscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000C2dwDMAR",
                        EmailAddresses = new List<string> { "mariacarmenco@unops.org", "luc.bagur@ec.europa.eu" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("mariacarmenco@unops.org".ToLower()) ? paoUserEmailMapping["mariacarmenco@unops.org".ToLower()] : 0,
