                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000DVljGMAT",
                        EmailAddresses = new List<string> { "jean-francoisl@unops.org", "emiliep@unops.org", "youssif.aboali@un.org", "aureliear@unops.org", "argitab@unops.org", "rehana.velji@un.org", "shereen.zorba@un.org" },
