                ),
                new (
                    "00TQx00000DWM9KMAX",
                    new UNOPSInteraction
                    {
                        Name = "Email: Meeting between UK and UNOPS Executive Director during UNGA?",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-07-22").ToUniversalTime(),
                        Subject = "Email: Meeting between UK and UNOPS Executive Director during UNGA?",
                        Description = "To: Agnes.Annells@fcdo.gov.uk; Sally.Clifford@fcdo.gov.uk\nCC: naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Meeting between UK and UNOPS Executive Director during UNGA?\nBody:\nDear colleagues at FCDO, \nOur Executive Director has asked for a bilateral meeting with a relevant UK representative during the UNGA. Jorge would greatly appreciate the opportunity to discuss the situation in especially Gaza and Ukraine.  \nMight you be able to help us advise on who from the UK side that might be suitable? Then we will send a more formal request for a bilateral meeting. \nThanks a lot in advance!\nBest,AsbjørnAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000DWM9KMAX",
                        EmailAddresses = new List<string> { "agnes.annells@fcdo.gov.uk", "naimoh@unops.org", "sally.clifford@fcdo.gov.uk" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
                        CreatedDate = new DateTime(2024, 7, 22, 9, 53, 48, DateTimeKind.Utc),
                        LastModifiedBy = 0,
