                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000DoMiuMAF",
                        EmailAddresses = new List<string> { "tushard@unops.org", "emiliep@unops.org", "alexandram@unops.org", "carolinapo@unops.org", "hilaryb@unops.org", "ingaro@unops.org", "camilafl@unops.org", "olgad@unops.org", "annag@unops.org", "victoriac@unops.org", "taranehd@unops.org", "stevenc@unops.org", "kirstined@unops.org", "kongleongt@unops.org", "valeriek@unops.org", "orenng@unops.org", "charlottet@unops.org", "nicolej@unops.org", "asbjornb@unops.org", "rahulm@unops.org", "svene@unops.org", "thomasl@unops.org", "vilhelmk@unops.org", "julial@unops.org", "johnap@unops.org", "insurs@unops.org", "felixfr@unops.org", "sonjalk@unops.org", "abdould@unops.org", "thorstenh@unops.org", "liliann@unops.org" },
