                    new UNOPSInteraction
                    {
                        Name = "Email: CONFIRMED: Meeting: IDB-UNOPS Informational session - Framework Agreement",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2023-08-31").ToUniversalTime(),
                        Subject = "Email: CONFIRMED: Meeting: IDB-UNOPS Informational session - Framework Agreement",
                        Description = "To: VITORIAL@iadb.org; SHIRLEYG@iadb.org; DENISEC@iadb.org; PATRICIAMAR@iadb.org; isabelaf@unops.org\nCC: \nBCC: \nAttachment: --none--\n\nSubject: CONFIRMED: Meeting: IDB-UNOPS Informational session - Framework Agreement\nBody:\nProposed Agenda:\n\na. Contextual overview\n\nb. Services to be provided – procurement agent; consultant (technical assistance); supplier.\n\nc. Presentation of the draft Framework Agreement & contract template.\n\ni. UNOPS is expected to provide initial feedback/reactions or highlight any areas needing clarification.\n\nd. Sharing and explanation of fiduciary checklist requirements.\n \n\n________________________________________________________________________________\n\n\n\n\nMicrosoft Teams meeting\n\n\n\n\nJoin on your computer, mobile app or room device\n\n\nClick\n here to join the meeting \n\n\n\nMeeting ID:\n231 918 281 141\n\n\nPasscode:\nff6saN\n\n\nDownload Teams |\n\nJoin on the web\n\n\n\n\nJoin with a video conferencing device\n\n\n\niadb@m.webex.com\n\n\n\nVideo Conference ID:\n114 289 131 2\n\n\n\nAlternate VTC instructions\n\n\n\n\nOr call in (audio only)\n\n\n\n+1 253-343-5838,,805316438#\n  United States, Tacoma\n\n\n\nPhone Conference ID:\n805 316 438#\n\n\nFind a local number\n | \nReset PIN \n\n\nLearn More |\n\nMeeting options \n\n\n\n________________________________________________________________________________",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000Dp25LMAR",
                        EmailAddresses = new List<string> { "vitorial@iadb.org", "patriciamar@iadb.org", "shirleyg@iadb.org", "iadb@m.webex.com", "isabelaf@unops.org", "denisec@iadb.org" },
                        Status = (EntityStatus)1,
