                new (
                    "00TQx00000Dp4VHMAZ",
                    new UNOPSInteraction
                    {
                        Name = "Email: Re: New Grant support policy",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-07-25").ToUniversalTime(),
                        Subject = "Email: Re: New Grant support policy",
                        Description = "To: mariacarmenco@unops.org\nCC: INTPA-PILLAR-ASSESSMENT@ec.europa.eu; LaetitiaK@unops.org; Amaya.OLIVARES-ZAPIAIN@ec.europa.eu; Afschin.LAGIES@ec.europa.eu; Liviu.PACALA@ec.europa.eu; Paolo.SERGIO@ec.europa.eu\nBCC: \nAttachment: --none--\n\nSubject: Re: New Grant support policy\nBody:\nPerfect\n\n\n\nAmaya will send you the details\n\n\n\nManos\nSent from my iPhone\n\n\nOn 25 Jul 2024, at 11:11, Mariacarmen COLITTI <mariacarmenco@unops.org> wrote:\n\n\n\n\n\n\n﻿\nSure!\n\n\n\nThank you. I will be back to Brussels on Monday and we will touch base with your colleagues in R. Should it be Audit and legal ones?\n\n\n\nBest regards \nCarmen\n\n\nMariacarmen Colitti | Head of Office and Representative | Partnerships and Liaison Group | Brussels Liaison Office | Brussels, Belgium | Tel: + 32 2 7881840|\n\nwww.unops.org \n\n\n\nKeep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube.\n\n\nSubscribe to our external newsletter in English, French or Spanish. \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nLe jeu. 25 juil. 2024 à 10:08, PAPAIOANNOU Emmanouil-Georgios <Emmanouil.Papaioannou@ec.europa.eu> a écrit :\n\n\n\nBut before doing that I would suggest that you have a meeting with my colleagues to clarify few issues\n\n\n\nThx\n\n\n\nManos \nSent from my iPhone\n\n\nOn 25 Jul 2024, at 11:00, PAPAIOANNOU Emmanouil-Georgios (INTPA) <Emmanouil.Papaioannou@ec.europa.eu> wrote:\n\n\n\n\n\n\n﻿ Dear Carmen\n\n\n\nYou can send it to me\n\n\n\nKind Regards \n\n\n\nManos \nSent from my iPhone\n\n\nOn 25 Jul 2024, at 09:34, Mariacarmen COLITTI <mariacarmenco@unops.org> wrote:\n\n\n\n\n\n\n﻿\nDear Manos,\n\n\n\nThank you for tour mail.\n\n\n\nWhen you say that we need to inform the Commission, to whom does the communication need to be addressed?\n\n\n\nBest regards,\nCarmen\n\n\nMariacarmen Colitti | Head of Office and Representative | Partnerships and Liaison Group | Brussels Liaison Office | Brussels, Belgium | Tel: + 32 2 7881840|\n\nwww.unops.org \n\n\n\nKeep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube.\n\n\nSubscribe to our external newsletter in English, French or Spanish. \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nLe jeu. 25 juil. 2024 à 07:31, PAPAIOANNOU Emmanouil-Georgios <Emmanouil.Papaioannou@ec.europa.eu> a écrit :\n\n\n\n\n\nDear Mariacarmen\n \nIf not done already, you need to officially inform the Commission about the change of your overall grant  support policy\n \nKind Regards\n \nManos\n \n\nFrom: Mariacarmen COLITTI <mariacarmenco@unops.org>\n\n\nSent: Thursday, April 25, 2024 4:50 PM\n\nTo: PAPAIOANNOU Emmanouil-Georgios (INTPA) <Emmanouil.Papaioannou@ec.europa.eu>\n\nCc: SERGIO Paolo (INTPA) <Paolo.SERGIO@ec.europa.eu>; Laetitia KRAUS <LaetitiaK@unops.org>\n\nSubject: New Grant support policy\n\n \n\n\nDear Manos,\n\n\n \n\n\nI hope all is well with you.\n\n\n \n\n\nBy this email I wish to inform you that we are currently negotiating a new financing agreement with INTPA A2, which includes - as requested by them - an ad hoc selection methodology  that was already pillar assessed\n in 2015.\n\n\n\nHowever, I wish to inform you that we have a new overall grant support policy (which does not change anything to the methodology that was assessed in 2015 and that we are using for this project), for future pillar assessment purposes.\n\n\n \n\n\nBest regards\n\n\nCarmen\n\n\n \n\n\n \n\n\n \n\n\n\n\n\n\n\n\nMariacarmen Colitti\n| Head of Office and Representative | Partnerships and Liaison Group | Brussels Liaison Office\n| Brussels, Belgium | Tel: + 32 2 7881840|\nwww.unops.org \n\nKeep up-to-date with UNOPS. Follow us on\nFacebook,\nLinkedIn,\nTwitter,\nInstagram,\nYouTube.\n\n\nSubscribe to our external newsletter in\n\nEnglish,\nFrench\n or \nSpanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000Dp4VHMAZ",
                        EmailAddresses = new List<string> { "laetitiak@unops.org", "intpa-pillar-assessment@ec.europa.eu", "liviu.pacala@ec.europa.eu", "paolo.sergio@ec.europa.eu", "mariacarmenco@unops.org", "amaya.olivares-zapiain@ec.europa.eu", "afschin.lagies@ec.europa.eu", "emmanouil.papaioannou@ec.europa.eu" },
                        Status = (EntityStatus)1,
