                ),
                new (
                    "00TQx00000DpPI2MAN",
                    new UNOPSInteraction
                    {
                        Name = "Email: Request for a bilateral meeting between the Under-Secretary-General and Executive Director of UNOPS and President of the IDB at the SIDS 4th Conference to be held in Antigua & Barbuda from May 27th to 30th.",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-05-21").ToUniversalTime(),
                        Subject = "Email: Request for a bilateral meeting between the Under-Secretary-General and Executive Director of UNOPS and President of the IDB at the SIDS 4th Conference to be held in Antigua & Barbuda from May 27th to 30th.",
                        Description = "To: SILVINAR@iadb.org; MACARENAF@iadb.org; VITORIAL@iadb.org; shirleyg@iadb.org\nCC: solv@unops.org; giuseppem@unops.org; antoinel@unops.org; isabelaf@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Request for a bilateral meeting between the Under-Secretary-General and Executive Director of UNOPS and President of the IDB at the SIDS 4th Conference to be held in Antigua & Barbuda from May 27th to 30th.\nBody:\nDear IDB colleagues,\n\nOn behalf of UN Under-Secretary-General and Executive Director of UNOPS, Mr. Jorge Moreira da Silva, may I kindly ask you to convey the attached letter to the attention of H. E. Mr. Ilan Goldfajn President of the Inter-American Development Bank.\nMany thanks for confirming the reception and transmission of this letter. \nWith best regards,Sarah Dubord-Gagnon| Senior Executive Assistant to Under-Secretary-General and Executive Director | UNOPS Executive Office | Copenhagen, Denmark | Tel: +45 31 48 69 15 | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000DpPI2MAN",
                        EmailAddresses = new List<string> { "giuseppem@unops.org", "vitorial@iadb.org", "shirleyg@iadb.org", "solv@unops.org", "macarenaf@iadb.org", "isabelaf@unops.org", "silvinar@iadb.org", "antoinel@unops.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("isabelaf@unops.org".ToLower()) ? paoUserEmailMapping["isabelaf@unops.org".ToLower()] : 0,
                        CreatedDate = new DateTime(2024, 7, 29, 16, 27, 14, DateTimeKind.Utc),
                        LastModifiedBy = 0,
                        LastModifiedDate = DateTime.UtcNow,
                        IsDeleted = false,
                        DeletedBy = 0
                    },
                    new List<string> { "003Qx00000MveYrIAJ" },
                    new List<int> { 1442 },
