                        GmailMessageId = "00TQx00000DthOMMAZ",
                        EmailAddresses = new List<string> { "kevin.luthi@theglobalfund.org", "caroline.mubangizi@theglobalfund.org", "mdmosiqure@gmail.com", "bodrudozaa@unops.org", "marufh@unops.org", "musfiqr2003@gmail.com", "shaikha@unops.org", "kuldipm@unops.org", "adn_dr@yahoo.com", "shahadthm@unops.org", "sudhirm@unops.org", "gyongyver.jakab@theglobalfund.org", "fahadm@unops.org", "iftekhara@unops.org", "nicholas.furtado@theglobalfund.org", "gyongyver.jakab@theglobafund.org", "zahiduli@unops.org", "dr.azad842492@gmail.com", "samudikad@unops.org", "sarwari@unops.org", "charlesc@unops.org", "dpmmalaria.shyamolkdas@gmail.com", "mohamedh@unops.org", "hashana@unops.org", "james.wariero@theglobalfund.org" },
