                    "00TQx00000DtsyOMAR",
                    new UNOPSInteraction
                    {
                        Name = "Email: UN-Habitat HR Services Report - July 2024",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-07-31").ToUniversalTime(),
                        Subject = "Email: UN-Habitat HR Services Report - July 2024",
                        Description = "To: lu.liu@un.org; joy.munene@un.org\nCC: LucyM@unops.org; lorrainea@unops.org; haris.pajtic@un.org; terryg@unops.org; kajsah@unops.org; amritan@unops.org\nBCC: \nAttachment: --none--\n\nSubject: UN-Habitat HR Services Report - July 2024\nBody:\nDear Joy and Lu,\nI hope my message finds you well.Please find attached the UN-Habitat  HR services report for July 2024 (retrieved on 31/07/2024). \n\nPlease note that this HR report should be regarded as a preliminary report – final and accurate data is reflected in our certified financial reports. \nLooking forward to hearing from you\nBest regards, Laurentiu Mastacan | HR Partnerships Analyst | PLG, Partnerships and Liaison Group | UNOPS Headquarters | Copenhagen, Denmark | Tel: +45 4533 7816 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube. \nSubscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000DtsyOMAR",
                        EmailAddresses = new List<string> { "amritan@unops.org", "lorrainea@unops.org", "lucym@unops.org", "terryg@unops.org", "joy.munene@un.org", "haris.pajtic@un.org", "lu.liu@un.org", "kajsah@unops.org" },
