                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000Du6fyMAB",
                        EmailAddresses = new List<string> { "amritan@unops.org", "runze.wang@un.org", "andre.dzikus@un.org", "emiliep@unops.org", "ran.wang@un.org", "aguirres@un.org", "erfan.ali@un.org", "kajsah@unops.org" },
