                ),
                new (
                    "00TQx00000Du8WVMAZ",
                    new UNOPSInteraction
                    {
                        Name = "Email: UNEP HR Services Report - July 2024",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-07-31").ToUniversalTime(),
                        Subject = "Email: UNEP HR Services Report - July 2024",
                        Description = "To: monica.otemba@un.org\nCC: kajsah@unops.org; amritan@unops.org; samsono@unops.org; LucyM@unops.org; terryg@unops.org; barraganc@un.org; edwin.onyach@un.org; cecilia.kibare@un.org; daniela.foot@un.org; isaac.kiama@un.org\nBCC: \nAttachment: --none--\n\nSubject: UNEP HR Services Report - July 2024\nBody:\nDear Monica,\n\nI hope my message finds you well.Please find attached the UNEP HR services report for July 2024 (retrieved on 31/07/2024). \nAdditional note: the highlighted resources/ personnel appear twice in the report due to the fact that a contract amendment will start during the respective month/ they have 2 active contracts while being on a retainer. Therefore if the report data is being used for counting the number of active personnel/sum up the expenditure triggered by the salaries then they could be deleted.\n\nPlease note that this HR report should be regarded as a preliminary report – final and accurate data is reflected in our certified financial reports. \nLooking forward to hearing from you\nBest regards, Laurentiu Mastacan | HR Partnerships Analyst | PLG, Partnerships and Liaison Group | UNOPS Headquarters | Copenhagen, Denmark | Tel: +45 4533 7816 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube. \nSubscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000Du8WVMAZ",
                        EmailAddresses = new List<string> { "amritan@unops.org", "samsono@unops.org", "lucym@unops.org", "terryg@unops.org", "barraganc@un.org", "isaac.kiama@un.org", "daniela.foot@un.org", "cecilia.kibare@un.org", "monica.otemba@un.org", "kajsah@unops.org", "edwin.onyach@un.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("kajsah@unops.org".ToLower()) ? paoUserEmailMapping["kajsah@unops.org".ToLower()] : 0,
