                new (
                    "00TQx00000EOnM6MAL",
                    new UNOPSInteraction
                    {
                        Name = "Email: UNOPS Gavi Ethiopia introduction",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-08-12").ToUniversalTime(),
                        Subject = "Email: UNOPS Gavi Ethiopia introduction",
                        Description = "To: lydiaat@unops.org; pmusanhu@gavi.org\nCC: \nBCC: \nAttachment: --none--\n\nSubject: UNOPS Gavi Ethiopia introduction\nBody:\nDear Lydia and Patience\nThis is to e-connect you as I understand there have been some conversations with Eunice in country.\nI would be happy to convene a short introductory meeting on line to have a more detailed discussion on the support that UNOPS could provide Gavi, given our large footprint and ongoing health related activities in Ethiopia.As you know we have just finalised our new Framework Agreement, so we are in good shape now to accelerate support as needed.\nLooking forward to hearing from you. With thanks and best wishesLouise\nLouise Leech, MPH  | Head of Geneva Liaison Office | Partnerships and Liaison Group | Mobile: +41 79 343 1614  UNOPS / Office des Nations Unies pour les Services Unité de Gestion du Projet\nGlobal project overview here  |  Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000EOnM6MAL",
                        EmailAddresses = new List<string> { "pmusanhu@gavi.org", "lydiaat@unops.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("louisel@unops.org".ToLower()) ? paoUserEmailMapping["louisel@unops.org".ToLower()] : 0,
