                        GmailMessageId = "00TQx00000EfWNFMA3",
                        EmailAddresses = new List<string> { "cdgas@senlsmr.org", "marionc@unops.org", "shirazd@unops.org", "cam@senlsmr.org", "dhouhaa@unops.org", "jakobt@unops.org", "didierg@unops.org", "daf@senlsmr.org", "desire-paul.gueye-massa@gfa-group.de", "sidialy@senlsmr.org", "ndeyemaguetten@unops.org", "herve.dalmeida@theglobalfund.org", "wisnaudd@unops.org", "deborah.asante-luisier@theglobalfund.org", "louisel@unops.org", "houcema@unops.org", "papes@unops.org", "abdoulazizs@unops.org" },
