                new (
                    "00TQx00000FCfoiMAD",
                    new UNOPSInteraction
                    {
                        Name = "Email: Opfølgning på Danmarks nye Afrika-strategi",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-09-02").ToUniversalTime(),
                        Subject = "Email: Opfølgning på Danmarks nye Afrika-strategi",
                        Description = "To: ketkar@um.dk\nCC: marikr@um.dk; julwin@um.dk; rikoln@um.dk\nBCC: \nAttachment: --none--\n\nSubject: Opfølgning på Danmarks nye Afrika-strategi\nBody:\nKære Ketil\nMange gange tillykke med Danmarks nye, flotte Afrikastrategi! Det er et imponerende arbejde - men gode ambitioner for det fremtidige samarbejde mellem Danmark og de afrikanske lande. \nHer i UNOPS har vi allerede med meget stor interesse læst jeres nye strategi - og vil meget gerne indgå i dialog om, hvordan vi kan hjælpe med at føre strategien ud i livet på jorden i tæt samarbejde med de lokale samarbejdspartnere. Det gælder ikke mindst når det kommer til klimavenlig infrastruktur, bæredygtige indkøbsprocesser og effektiv projektledelse - som er vores kernekompetencer. \nVores Regionale Direktør for Afrika regionen, Dalila Goncalves, hendes nærmeste medarbejdere samt jeg selv vil meget gerne mødes med dig og øvrige relevante medarbejdere mhp. at drøfte hvilke kapaciteter i UNOPS som evt. kunne understøtte den nye danske Afrika-strategi. \nDalila er i København den første uge i oktober (dvs. i perioden d. 30 september til d. 4. oktober). Ville det evt. være muligt at finde et tidspunkt i løbet af den uge, hvor vi kunne kigge forbi Asiatisk Plads?\nJeg står naturligvis helt til jeres rådighed for evt. opfølgende spørgsmål og behov for afklaringer. \nPå forhånd mange tak!\nMvhAsbjørnAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000FCfoiMAD",
                        EmailAddresses = new List<string> { "rikoln@um.dk", "julwin@um.dk", "marikr@um.dk", "ketkar@um.dk" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
