                ),
                new (
                    "00TQx00000FCsfFMAT",
                    new UNOPSInteraction
                    {
                        Name = "Email: Opfølgning på Norges nye Afrikastrategi - besøg fra UNOPS i Oslo?",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-09-02").ToUniversalTime(),
                        Subject = "Email: Opfølgning på Norges nye Afrikastrategi - besøg fra UNOPS i Oslo?",
                        Description = "To: Stein.Erik.Horjen@norad.no; Constantin.Nicolaysen.Karame@mfa.no\nCC: naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Opfølgning på Norges nye Afrikastrategi - besøg fra UNOPS i Oslo?\nBody:\nKære Stein Erik og Constantin, \nJeg håber at i hvert fald Constantin er kommet godt tilbage til Oslo - uden alt for meget jetlag.\nSom kort drøftet over en kop kaffe i New York, vil vi meget gerne følge op på Norges nye Afrikastrategi. Vi ser en hel del muligheder for, at nogle af UNOPS' kernekompetencer i forhold til for eksempel klimavenlig infrastruktur, bæredygtige indkøbsprocesser og effektiv projektledelse kan bidrage til at føre de nye norske mål for bistanden til Afrika ud i livet.\nVores Regionale Direktør for Afrika, Dalila Goncalves, et par af hendes nærmeste medarbejdere samt jeg selv vil derfor meget gerne besøge jer og jeres kolleger i Oslo med henblik på at drøfte nærmere, hvordan samarbejdet mellem Norge og UNOPS evt. kan udbygges i Afrika. \nDalia, hendes nærmeste medarbejdere og jeg selv og min medarbejder Naimo (cc) har mulighed for at rejse en dag til Oslo i den første uge af oktober (dvs. 30. september - 4. oktober). \nKunne I være behjælpelig med at identificere hvilken dag der ville være mest hensigtsmæssig for et besøg i Oslo? Samt hvem der vil være mest relevante for Dalila at mødes med fra hhv. NORAD og Utenrigsdepartementet - som arbejder med det norske engagement i Afrika? \nPå forhånd mange tak!\nMvhAsbjørn       Asbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000FCsfFMAT",
                        EmailAddresses = new List<string> { "stein.erik.horjen@norad.no", "constantin.nicolaysen.karame@mfa.no", "naimoh@unops.org" },
                        Status = (EntityStatus)1,
