                ),
                new (
                    "00TQx00000FWF8FMAX",
                    new UNOPSInteraction
                    {
                        Name = "Email: Re: Opfølgning på Danmarks nye Afrika-strategi",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-09-10").ToUniversalTime(),
                        Subject = "Email: Re: Opfølgning på Danmarks nye Afrika-strategi",
                        Description = "To: ketkar@um.dk\nCC: casjen@um.dk; fenyam@um.dk; julwin@um.dk; rikoln@um.dk; naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Re: Opfølgning på Danmarks nye Afrika-strategi\nBody:\nKære Ketil \nJeg rækker ud som opfølgning på nedenstående mhp. på at høre, om du muligvis havde haft mulighed for at undersøge om du og dine kolleger evt. havde tid til at mødes på et tidspunkt i perioden mellem d. 30. september og 4. oktober? \nHensigten med mødet vil være drøfte UNOPS' kapaciteter i Afrika til at understøtte implementering af den nye danske Afrika-strategi. \nPå forhånd mange tak! \nMvhAsbjørn\nOn Mon, 2 Sept 2024 at 11:20, Asbjorn BRINK <asbjornb@unops.org> wrote:\nKære Ketil\nMange gange tillykke med Danmarks nye, flotte Afrikastrategi! Det er et imponerende arbejde - men gode ambitioner for det fremtidige samarbejde mellem Danmark og de afrikanske lande. \nHer i UNOPS har vi allerede med meget stor interesse læst jeres nye strategi - og vil meget gerne indgå i dialog om, hvordan vi kan hjælpe med at føre strategien ud i livet på jorden i tæt samarbejde med de lokale samarbejdspartnere. Det gælder ikke mindst når det kommer til klimavenlig infrastruktur, bæredygtige indkøbsprocesser og effektiv projektledelse - som er vores kernekompetencer. \nVores Regionale Direktør for Afrika regionen, Dalila Goncalves, hendes nærmeste medarbejdere samt jeg selv vil meget gerne mødes med dig og øvrige relevante medarbejdere mhp. at drøfte hvilke kapaciteter i UNOPS som evt. kunne understøtte den nye danske Afrika-strategi. \nDalila er i København den første uge i oktober (dvs. i perioden d. 30 september til d. 4. oktober). Ville det evt. være muligt at finde et tidspunkt i løbet af den uge, hvor vi kunne kigge forbi Asiatisk Plads?\nJeg står naturligvis helt til jeres rådighed for evt. opfølgende spørgsmål og behov for afklaringer. \nPå forhånd mange tak!\nMvhAsbjørnAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000FWF8FMAX",
                        EmailAddresses = new List<string> { "fenyam@um.dk", "julwin@um.dk", "naimoh@unops.org", "rikoln@um.dk", "casjen@um.dk", "asbjornb@unops.org", "ketkar@um.dk" },
