                new (
                    "00TQx00000Ff59dMAB",
                    new UNOPSInteraction
                    {
                        Name = "Email: Mulighed for foretræde for Udenrigsudvalget for FN-Undergeneralsekretær og Executive Director for UNOPS",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-09-13").ToUniversalTime(),
                        Subject = "Email: Mulighed for foretræde for Udenrigsudvalget for FN-Undergeneralsekretær og Executive Director for UNOPS",
                        Description = "To: niklas.bjerre@ft.dk; amalie.andresen@ft.dk\nCC: naimoh@unops.org; folketinget@ft.dk\nBCC: \nAttachment: --none--\n\nSubject: Mulighed for foretræde for Udenrigsudvalget for FN-Undergeneralsekretær og Executive Director for UNOPS\nBody:\nKære Niklas og Amalie, \nJeg kontakter jer på vegne af FN Byen i København samt UNOPS, med henblik på at indlede dialog om mulighed for foretræde for Udvalget.  \nFormålet med dialogen vil være at afsøge muligheden for, at FN Byens øverste chef, FN-Under-Generalsekretær og Executive Director for UNOPS, Jorge Moreira da Silva kan få foretræde for Udvalget. \nFN Under-Generalsekretæren ønsker bl.a. at orientere Udvalget om situationen i Gaza og Ukraine samt at informere Udvalget om FN's arbejde i de mest konfliktramte områder - herunder også FN's vurdering af situationen. \nHerudover ønsker FN Under-Generalsekretæren at informere Udvalget om det konkrete arbejde som udføres af FN agenturerne i København, herunder særligt UNOPS, der som det eneste FN-agentur har hovedkvarter i København.\nJeg ser meget frem til at høre fra jer. \nPå forhånd tak. \nMvhAsbjørn Asbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000Ff59dMAB",
                        EmailAddresses = new List<string> { "folketinget@ft.dk", "niklas.bjerre@ft.dk", "amalie.andresen@ft.dk", "naimoh@unops.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
                        CreatedDate = new DateTime(2024, 9, 13, 8, 47, 20, DateTimeKind.Utc),
                        LastModifiedBy = 0,
                        LastModifiedDate = DateTime.UtcNow,
                        IsDeleted = false,
