                ),
                new (
                    "00TQx00000GigkaMAB",
                    new UNOPSInteraction
                    {
                        Name = "Email: Re: [RE]Re: [RE]Re: [RE][유놉스] 아시아 Regional Director 이사장님 미팅 관련",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-10-09").ToUniversalTime(),
                        Subject = "Email: Re: [RE]Re: [RE]Re: [RE][유놉스] 아시아 Regional Director 이사장님 미팅 관련",
                        Description = "Communication from Anna (Yoo Gyoung) Kim to Ms. Baek : \nWe will reschedule visit from UNOPS HQ/APR early next year in Q1. We will come back with few date options about 1 ~ 1.5 months prior to tentative travel dates and request for KOICA President availability. It was also mentioned that there may be delegation from UNOPS HQ as well.",
                        Location = null,
