                        Date = DateTime.Parse("2024-10-22").ToUniversalTime(),
                        Subject = "Email: Novo Nordisk support to Ukraine",
                        Description = "To: eleneag@unops.org; asbjornb@unops.org\nCC: \nBCC: \nAttachment: --none--\n\nSubject: Novo Nordisk support to Ukraine\nBody:\nDear Elene and Asbjørn\n\n \nI am now back from vacation and really pleased to see the announcement on our collaboration around our support to Ukraine.\n\n \nAs you have seen and agreed to, we will not be able to transfer any funds before 2025. In order to be ready for transferring our funding it would be\n great if we can move forward with the legal / contract work. I believe that we have to use a UNOPS contract template or would it be possible to use Novo Nordisk contract template which would make things much easier in our end ?\n\n \nIn case it is a UNOPS template that we have to use I would ask you to prepare the contract in order for me to share it with our legal team.\n\n \nI look forward to your reply.\n\n \n\n\n\n\n\n\n\n\n\nKind regards\n\n\n\n\n\nUlrik Uldall Nielsen\n\n\n\n\n\nPrevention Advocacy Lead\n\n\n\n\n\n9405 Advocacy and Partnerships\n\n\n\n\n\n+45-30754738 (mobile)\n\n\n\n\n\nUUNI@novonordisk.com\n\n\n\n\n\nNovo Nordisk A/S ǀ\n Krogshøjvej 46 ǀ\n DK-2880 Bagsværd ǀ\n +45 4444 8888 (switchboard) ǀ\n novonordisk.com ǀ \nFacebook ǀ \nLinkedin ǀ \nInstagram ǀ \nX (Twitter) ǀ \nYouTube ǀ \nTikTok\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n \n\n\n\n\nThis e-mail (including any attachments) is intended for the addressee(s) stated above only and may contain confidential information\n protected by law. You are hereby notified that any unauthorised reading, disclosure, copying or distribution of this e-mail or use of information contained herein is strictly prohibited and may violate rights to proprietary information. If you are not an intended\n recipient, please return this e-mail to the sender and delete it immediately hereafter.\nThank you.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000HCrGnMAL",
                        EmailAddresses = new List<string> { "asbjornb@unops.org", "eleneag@unops.org", "uuni@novonordisk.com" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
