                    new List<string> { "B0047" }
                ),
                new (
                    "00TQx00000HSsoZMAT",
                    new UNOPSInteraction
                    {
                        Name = "Email: Request for a meeting with Minister of State for Development and Minister of State for Women and Equalities",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-10-29").ToUniversalTime(),
                        Subject = "Email: Request for a meeting with Minister of State for Development and Minister of State for Women and Equalities",
                        Description = "To: Agnes.Annells@fcdo.gov.uk\nCC: Sally.Clifford@fcdo.gov.uk; naimoh@unops.org; kerriet@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Request for a meeting with Minister of State for Development and Minister of State for Women and Equalities\nBody:\nDear Agnes,\nUN Under-Secretary General and UNOPS Executive Director, Mr. Jorge Moriera da Silva is kindly requesting a meeting with Minister of State for Development and Minister of State for Women and Equalities, Ms. Anneliese Dodds during the COP29. \nUSG Moreira would very much like to use the opportunity to discuss topics relevant for the upcoming strategic dialogue between the UK and UNOPS and to inform the minister about UNOPS' work in fragile and conflict affected places such as Gaza, Ukraine, Yemen, the Sahel, etc. \nThe USG will be at the COP on 12-15 November. \nThank you very much in advance for bringing this request to the attention of the Minister. \nI look forward to hearing from you. \nBest regards,Asbjørn\nAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000HSsoZMAT",
                        EmailAddresses = new List<string> { "agnes.annells@fcdo.gov.uk", "kerriet@unops.org", "naimoh@unops.org", "sally.clifford@fcdo.gov.uk" },
                        Status = (EntityStatus)1,
