                new (
                    "00TQx00000Hm0KIMAZ",
                    new UNOPSInteraction
                    {
                        Name = "Email: Next Steps: ASG Madi & ASG Damkjær - Partnership Dialogue",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-11-05").ToUniversalTime(),
                        Subject = "Email: Next Steps: ASG Madi & ASG Damkjær - Partnership Dialogue",
                        Description = "To: sitara.sofizada@unwomen.org; shuyu.luo@unwomen.org\nCC: mikaelag@unops.org; jakobt@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Next Steps: ASG Madi & ASG Damkjær - Partnership Dialogue\nBody:\nDear Sitara and Shuyu, \nThank you once again for your kind support in organizing the virtual call between ASG Madi and ASG Damkjær on 28 October. \nI am reaching out to coordinate the next steps based on the action points agreed upon during the meeting last week, particularly the scheduling of a 1-hour virtual partnership dialogue between ASG Madi and ASG Damkjær, joined by sectoral experts from each agency.\nTo facilitate planning, may I kindly suggest the following time slots for this 1-hour meeting:\nTuesday, 3 December, between 15:00 and 17:00 (CET)Thursday, 5 December, between 15:00 and 17:00 (CET)\nPlease find here and attached a suggested agenda for the meeting, we warmly welcome UN Women’s views. \nAdditionally, my colleagues and I would greatly appreciate it if you could kindly confirm the email for Mitushi Dash, Senior Advisor to the Deputy Executive Director, who we understand will act as the focal point on UN Women’s side for this dialogue. \nThank you in advance for your assistance.\nWarm regards, \nWaing\nWaing Chit Aung (Mr) | Senior Associate - Executive Assistant to UN Assistant-Secretary-General and Deputy Executive Director (Delivery & Partnership)| UNOPS Executive Office | Marmorvej 51 2100 Copenhagen | Tel: +45 4533 7521",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000Hm0KIMAZ",
                        EmailAddresses = new List<string> { "shuyu.luo@unwomen.org", "mikaelag@unops.org", "sitara.sofizada@unwomen.org", "jakobt@unops.org" },
                        Status = (EntityStatus)1,
