                        EmailAddresses = new List<string> { "aaguero@unicef.org", "snuvoli@unicef.org", "chiara.musella@esteri.it", "mariacarmenco@unops.org", "jeromedt@unops.org", "mariagabriella.riso@esteri.it" },
                        Status = (EntityStatus)1,
