bi@eeas.europa.eu", "stephan.fox@eeas.europa.eu", "wim.vandenbroucke@eeas.europa.eu", "fabio.di-stefano@ec.europa.eu", "lenaic.georgelin@ec.europa.eu", "cecile.tassin-pelzer@ec.europa.eu", "jerome.pons@eeas.europa.eu", "jules.kembou@eeas.europa.eu", "joost.mohlmann@eeas.europa.eu", "niccolo.maracchi@eeas.europa.eu", "ally.mwinchande@eeas.europa.eu", "caroline.adriaensen@eeas.europa.eu", "jesus-manuel.gavilan-marin@ec.europa.eu", "nicolas.masson@eeas.europa.eu", "madalina.hurjui@ec.europa.eu", "macarena.ruiz-san-jose@ec.europa.eu", "adela.rodenas-rodriguez@eeas.europa.eu", "stefan.lock@eeas.europa.eu", "marc.stalmans@ec.europa.eu", "carine.villemagne-cros@ec.europa.eu", "emmanuel.soubiran@eeas.europa.eu", "hugo.zsolt-de-sousa@eeas.europa.eu", "george.dura@ec.europa.eu", "valerie-catherine.heyvaert@ec.europa.eu", "irene.giribaldi@eeas.europa.eu", "sacha.dekeyser@ec.europa.eu", "gabriel-octavian.leonte@eeas.europa.eu", "mohamed.haji@eeas.europa.eu", "virginie.de-ruyt@ec.europa.eu", "roberto.schiliro@eeas.europa.eu", "augustin.tshiani@eeas.europa.eu", "antonio.capone@eeas.europa.eu", "daniela.rofi@ec.europa.eu", "jeromedt@unops.org", "patrick.illing@eeas.europa.eu", "aklilu.desta@eeas.europa.eu" },
