                        GmailMessageId = "00TQx00000JxBkbMAF",
                        EmailAddresses = new List<string> { "mariegoreth.nizigama@unwomen.org", "sadou.doumbo@unwomen.org", "coulibalyadama69@yahoo.fr", "marie.uwitonze@un.org", "aissata.diodo.dia@undp.org", "o.dicko@unesco.org", "abdoulkarim.bah@fao.org", "sabam@unaids.org", "pngom@unicef.org", "abderrahman.elyessa@un.org", "ia.cisse@unesco.org", "sadoudoumbo@unwomen.org", "diourteb@yahoo.fr", "fatoumata.tata.toure@undp.org", "roland.seri@undp.org", "itamac@who.int", "hady.sangare@unwomen.org", "mahmoudghouil@gmail.com", "ould@unfpa.org", "kassoum.daouda.minta@undp.org", "bsaadallaoui@unicef.org", "ibrahima.diallo@wfp.org", "boureimamaiga@yahoo.com", "moussalc@yahoo.fr", "khassim.diagne@un.org", "maleye.diop@undp.org", "francis.negue@un.org", "idris.bexi@undp.org", "michaeld@unops.org", "h.sowtraore@unido.org", "touredne2002@yahoo.fr", "kahoui@un.org", "oumar.tamboura@undp.org", "s.marrouki@gnet.tn", "idrissaatraore@gmail.com", "abdoulazizs@unops.org" },
