                new (
                    "00TQx00000KHDdSMAX",
                    new UNOPSInteraction
                    {
                        Name = "Email: SV: Project 24129. Update on Arkas Project.",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-01-14").ToUniversalTime(),
                        Subject = "Email: SV: Project 24129. Update on Arkas Project.",
                        Description = "To: teresam@unops.org\nCC: artvas@um.dk; arunn@unops.org; svitlanaz@unops.org; asbjornb@unops.org; marysiaz@unops.org; massimodi@unops.org; sungud@um.dk\nBCC: \nAttachment: --none--\n\nSubject: SV: Project 24129. Update on Arkas Project.\nBody:\nDear Teresa\n\n\n\nHappy new year!\n\n\n\nThank you for this update, I am very happy to hear that you reached an understanding with the local authorities regarding the emergency works. Looking forward to hearing about how you consolidate the tripartite agreement with CCD and whether more from our side\n is required for this.\n\n\n\nBest regards, \n\nJakob\n \n\n\nFra: Teresa MOLERO RODRIGUEZ <teresam@unops.org>\n\n\nSendt: 13. januar 2025 16:16\n\nTil: Jakob Torrild Hansen <jakhas@um.dk>; Sune Hjelmervik Gudnitz <sungud@um.dk>\n\nCc: Artem Vasalatii <artvas@um.dk>; Arun NARAYANAN <arunn@unops.org>; Svitlana ZAKRYNYTSKA <svitlanaz@unops.org>; Asbjorn BRINK <asbjornb@unops.org>; Marysia ZAPASNIK <marysiaz@unops.org>; Massimo DIANA <massimodi@unops.org>\n\nEmne: Project 24129. Update on Arkas Project.\n\n\n \n[CAUTION - EXTERNAL EMAIL] This email was sent from outside the MFA organisation. DO NOT reply, click on links, or open attachments unless you have verified\n the sender and know the content is safe.\n\n\n\nDear all,\n\n\n\nI hope this message finds you well.\n\n\n\nI would like to share that critical emergency work began last week in Arkas. This phase focuses on the stabilization of critical elements, particularly part of the ceilings, roof, and walls.\n\n\n\nUNOPS is closely supervising the work alongside our technical team to maintain the required standards of Quality and Health and Safety throughout the process.\n\n\n\nAs we move forward, I extend my warmest wishes for a Happy New Year to each of you.\n\n\n\nBest,  \n\nTeresa\n\n\n \n\n-- \n\n\n\nTeresa Molero Rodríguez (Ella/She/her) | \n Senior Project Manager |  Mykolaiv Infrastructure Project | UNOPS Ukraine Multi-Country Office |  Mykolaiv, Ukraine | Tel:  +34618939839\n 7 +380669645309   | Follow\n us on social media and\nsubscribe\n to our newsletter. | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000KHDdSMAX",
                        EmailAddresses = new List<string> { "sungud@um.dk", "jakhas@um.dk", "massimodi@unops.org", "arunn@unops.org", "marysiaz@unops.org", "svitlanaz@unops.org", "asbjornb@unops.org", "artvas@um.dk", "teresam@unops.org" },
