                new (
                    "00TQx00000KX9m5MAD",
                    new UNOPSInteraction
                    {
                        Name = "Email: Dates for Strategic Dialogue",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-01-20").ToUniversalTime(),
                        Subject = "Email: Dates for Strategic Dialogue",
                        Description = "To: simon.Hampton-ball@energysecurity.gov.uk; Agnes.Annells@fcdo.gov.uk; Sally.Clifford@fcdo.gov.uk\nCC: naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Dates for Strategic Dialogue\nBody:\nDear Agnes, Sally and Simon\nMy Executive Director Jorge would very much like for us to get the dates for the strategic dialogue between the UK and UNOPS settled as well as the bilateral meetings. Taking into consideration the new developments in the Middle East (Gaza, Syria and Lebanon), we find it even more pertinent to meet up. \nJorge has suggested coming to London on April 6 in the evening, spend the entire day in London on April 7 and then return to Copenhagen on April 8 in the morning. \nSo, might April 7 work on your side for a Strategic Dialogue?\nThank you in advance!\nBest,Asbjørn\n\n-- \n\nAsbjørn Brink| Head of Northern Europe Liaison Office | Partnerships and Liaison Group | HQ | Copenhagen, Denmark | Tel: +45 40 80 36 54 | Follow us on social media and subscribe to our newsletter. | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000KX9m5MAD",
                        EmailAddresses = new List<string> { "simon.hampton-ball@energysecurity.gov.uk", "agnes.annells@fcdo.gov.uk", "naimoh@unops.org", "sally.clifford@fcdo.gov.uk" },
