                    new UNOPSInteraction
                    {
                        Name = "Email: Request for meetings between The Rt Hon David Lammy & Baroness Chapman of Darlington and UN Under-Secretary-General and UNOPS Executive Director, Jorge Moreira da Silva",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-03-27").ToUniversalTime(),
                        Subject = "Email: Request for meetings between The Rt Hon David Lammy & Baroness Chapman of Darlington and UN Under-Secretary-General and UNOPS Executive Director, Jorge Moreira da Silva",
                        Description = "To: Agnes.Annells@fcdo.gov.uk\nCC: kerriet@unops.org; asbjornb@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Request for meetings between The Rt Hon David Lammy & Baroness Chapman of Darlington and UN Under-Secretary-General and UNOPS Executive Director, Jorge Moreira da Silva\nBody:\nDear Agnes,\nI hope this email finds you well.\nI will be travelling to London on 7 April, and would like to request meetings with The Rt Hon David Lammy, as well as Baroness Chapman of Darlington while I'm there.\nMay I please ask for your kind support in bringing the attached letters of request to the attention of The Rt hon David Lammy and Baroness Chapman of Darlington. \nIf agreed, my assistant Kerrie (copied), would be happy to work with you to schedule the meetings. \nIf you have any questions, please don't hesitate to let us know.\nMany thanks in advance.\n-- \nSincerely,Jorge Moreira da SilvaUN Under-Secretary-General and UNOPS Executive Director\nSent on behalf of USG Moreira da Silva\nUNOPS Executive Office | Copenhagen, Denmark | Follow us on social media and subscribe to our newsletter. | www.unops.org",
                        Location = null,
