                ),
                new (
                    "00TQx00000NmT5rMAF",
                    new UNOPSInteraction
                    {
                        Name = "Email: Anmodning om møde med direktør for The Sanitation and Hygiene Fund d. 5/6 maj",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-04-09").ToUniversalTime(),
                        Subject = "Email: Anmodning om møde med direktør for The Sanitation and Hygiene Fund d. 5/6 maj",
                        Description = "To: ketkar@um.dk; karpou@um.dk; adwmoh@um.dk; tavest@um.dk\nCC: rikoln@um.dk; naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Anmodning om møde med direktør for The Sanitation and Hygiene Fund d. 5/6 maj\nBody:\nKære kolleger på Asiatisk Plads, \nD. 5-6 maj kommer Executive Direktøren for The Sanitation and Hygiene Fund (SHF) - Dominic O'Nell - på besøg i København. Han har i den forbindelse udtryk ønske om at mødes med relevante i det danske Udenrigsministerium mhp. at orientere om SHF's arbejde. \nVi ville derfor sætte stor pris på, om I evt- havde tid til at mødes på et tidspunkt d. 5. eller 6. maj, til en kort introduktion til SHF's arbejde? Lad mig meget gerne vide hvornår det kunne passe for jer. \nTil jeres baggrundsinformation arbejder SHF for at forbedre sanitære forhold i udviklingslande med fokus på at: Sikre adgang til toiletter og handvaskfaciliteter i skoler, sundhedscentre og lokalsamfundUddanne folk i god hygiejnepraksis, herunder håndvask, madlavning og affaldsbehandlingReducere spredningen af sygdomme som diarré, kolera og tyfus, der ofte er forbundet med dårlige sanitære forholdI dag mangler næsten halvdelen af verdens befolkning adgang til sikker og forsvarlig sanitet, og en ud af fire kvinder på verdensplan kan ikke håndtere deres menstruation sikkert. Det er disse forhold, som SHF arbejder på at forbedre - pt. primært i Kenya, Nigeria og Uganda med planer om udvidelse til Vestafrika og Asien.\nJeg vedlægger til jeres baggrundsinformation et par one-pagers om SHF's initiativer. \nJeg ser frem til at høre fra jer. \nPå forhånd mange tak. \nMvhAsbjørn\n-- \n\nAsbjørn Brink| Head of Northern Europe Liaison Office | Partnerships and Liaison Group | HQ | Copenhagen, Denmark | Tel: +45 40 80 36 54 | Follow us on social media and subscribe to our newsletter. | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000NmT5rMAF",
                        EmailAddresses = new List<string> { "adwmoh@um.dk", "naimoh@unops.org", "rikoln@um.dk", "tavest@um.dk", "karpou@um.dk", "ketkar@um.dk" },
