                    "00TQx00000OGag2MAD",
                    new UNOPSInteraction
                    {
                        Name = "Email: SIDS4 Conference",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-05-13").ToUniversalTime(),
                        Subject = "Email: SIDS4 Conference",
                        Description = "To: y.ferreira@eib.org\nCC: giuseppem@unops.org\nBCC: \nAttachment: --none--\n\nSubject: SIDS4 Conference\nBody:\nQuerido Yves, \nEsperando que estés muy bien, gusto saludarte. Queríamos consultarte si habrá una delegación del BEI en el 4th International Conference on Small Island Developing States, del 27 al 30 de Mayo en Antigua. De UNOPS estará Giuseppe liderando nuestra delegación regional, y sería ideal poder generar un encuentro e invitarles a alguna de las actividades donde estaremos participando.\nSaludos,\n\nMrs. Isabela Fraiz | Senior Associate for Partnerships & Communications | Regional Office for Latin America and the Caribbean | Panama | Tel: +507 306 3638 | Mob: +507 648 39508 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube. Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000OGag2MAD",
                        EmailAddresses = new List<string> { "giuseppem@unops.org", "y.ferreira@eib.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("isabelaf@unops.org".ToLower()) ? paoUserEmailMapping["isabelaf@unops.org".ToLower()] : 0,
