                ),
                new (
                    "00TQx00000PX5qjMAD",
                    new UNOPSInteraction
                    {
                        Name = "Email: Re: Proposed Communication Plan - Sint Maarten",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-05-22").ToUniversalTime(),
                        Subject = "Email: Re: Proposed Communication Plan - Sint Maarten",
                        Description = "To: sofiatr@unops.org\nCC: rosst@unops.org; antonioba@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Re: Proposed Communication Plan - Sint Maarten\nBody:\nThank you Sofia, this is greatly appreciated.\nPlease share with ismery and the cabinet for feedback and next steps.\nThis is greatly appreciated.\n\nKind regardsWilliam SQUIER GONZALEZ\nHead of Programme | ICMCO | LCR\nSan Jose, Costa Rica | Tel: +506 8337 9154Follow us on social media and subscribe to our newsletter. | www.unops.org\n\nEl El mié, 21 may 2025 a la(s) 9:55 p. m., Sofia TREJOS <sofiatr@unops.org> escribió:\nDear all,\nHere you can find the proposed communication plan for the prison incident. I appreciate your review and remain available to present it in a meeting if needed.\nI remain attentive to comments. \nRegards\n\n-- \nSofía Trejos Lépiz (she/her) | Oficial Senior de Comunicaciones | LCR | PAMCO | San José,  (Costa Rica) | Tel.: +506 4081 0040 | Mobile: (WhatsApp): +506 8704 2199 | Síganos en las redes sociales y suscríbase a nuestro boletín informativo | www.unops.org/es | www.proyectoscostarica.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000PX5qjMAD",
                        EmailAddresses = new List<string> { "antonioba@unops.org", "sofiatr@unops.org", "rosst@unops.org" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("williamsg@unops.org".ToLower()) ? paoUserEmailMapping["williamsg@unops.org".ToLower()] : 0,
